      "content": "import { assert } from 'node:assert/strict';

const TTL_MS = 5000; // 5 seconds

/** @type {Map<string, number>} */
const activeLeases = new Map();

function assertValidSubject(key) {
  if (typeof key !== 'string' || key.length === 0) {
    throw new Error('subject must be a non‑empty string');
  }
}

/**
 * Grants a lease for the given subject if none is active.
 * @param {string} subject
 * @returns {boolean} true if lease granted, false if already held.
 * @throws {Error} on invalid subject.
 */
export function grantLease(subject) {
  assertValidSubject(subject);
  const now = Date.now();
  const existing = activeLeases.get(subject);
  if (existing && existing > now) {
    // lease still active
    return false;
  }
  // capacity check – we allow only one active lease per subject.
  activeLeases.set(subject, now + TTL_MS);
  return true;
}

/**
 * Revokes an active lease for the given subject.
 * @param {string} subject
 * @returns {boolean} true if lease was revoked, false if none existed.
 * @throws {Error} on invalid subject.
 */
export function denyLease(subject) {
  assertValidSubject(subject);
  return activeLeases.delete(subject);
}

/**
 * Checks whether a lease is currently held for the subject.
 * @param {string} subject
 * @returns {boolean} true if lease is active.
 * @throws {Error} on invalid subject.
 */
export function isLeaseHeld(subject) {
  assertValidSubject(subject);
  const expiry = activeLeases.get(subject);
  return expiry && expiry > Date.now();
}
