import assert from 'node:assert/strict';
import { grantLease, denyLease, isLeaseHeld } from './leaseHelper.js';

test('grant lease for valid subject', () => {
  assert.ok(grantLease('alpha'));
  assert.ok(isLeaseHeld('alpha'));
});

test('cannot grant duplicate lease while active', () => {
  // second grant immediately should fail
  assert.strictEqual(grantLease('alpha'), false);
});

test('deny lease revokes it', () => {
  assert.strictEqual(denyLease('alpha'), true);
  assert.strictEqual(isLeaseHeld('alpha'), false);
});

test('deny lease on non‑existent lease returns false', () => {
  assert.strictEqual(denyLease('beta'), false);
});

test('grant lease with invalid subject throws', () => {
  assert.throws(() => grantLease(null), Error);
  assert.throws(() => grantLease(42), Error);
  assert.throws(() => grantLease(''), Error);
});

test('deny lease with invalid subject throws', () => {
  assert.throws(() => denyLease(null), Error);
  assert.throws(() => denyLease(''), Error);
});
